"""Tests for remote session discovery, lifecycle, and persistence."""

from unittest.mock import patch

import pytest

from claude_dashboard import config
from claude_dashboard.config import StatusState
from claude_dashboard.controller import AppController, _SessionEntry
from claude_dashboard.otel_state import SessionState
from claude_dashboard.session import SessionInfo
from claude_dashboard.settings import Settings

# The machine running the tests could be named anything — including the
# hostname used as "remote" in fixtures. Pin the local hostname so the
# local-vs-remote comparison never depends on the real environment.
_LOCAL = "local-test-host"


@pytest.fixture(autouse=True)
def _pin_local_hostname():
    with patch("claude_dashboard.config.LOCAL_HOSTNAME", _LOCAL):
        yield


def _make_controller() -> AppController:
    """Build a bare controller with just the state the OTEL path touches."""
    c = object.__new__(AppController)
    c._sessions = {}
    c._session_id_to_pid = {}
    c._next_synthetic_pid = -1
    c._settings = Settings()
    c._saved_state = {}
    c._refresh_ui = lambda: None  # type: ignore[method-assign]
    return c


def _remote_state(
    *,
    state: StatusState = StatusState.WORKING,
    host: str = "remote-host-1",
    headless: bool = False,
) -> SessionState:
    return SessionState(
        state=state,
        host_name=host,
        project="/home/user/src/foo",
        location="~/src/foo",
        headless=headless,
    )


def _poll(
    controller: AppController, states: dict[str, SessionState], *, at: float = 1000.0
) -> None:
    """Run one OTEL poll. `at` is the wall clock the poll sees — advance it
    past REMOTE_METRIC_GRACE_SECONDS to age a missing remote row out."""
    with patch("claude_dashboard.controller.poll_session_states", return_value=states):
        with patch("claude_dashboard.controller._now_epoch", return_value=at):
            controller._update_states_from_otel()


_AFTER_GRACE = 1000.0 + config.REMOTE_METRIC_GRACE_SECONDS


def _entry_for(controller: AppController, session_id: str) -> _SessionEntry:
    return controller._sessions[controller._session_id_to_pid[session_id]]


class TestRemoteDiscovery:
    def test_unmatched_remote_host_creates_entry(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state()})
        entry = _entry_for(c, "abc")
        assert entry.remote_host == "remote-host-1"
        assert entry.session.cwd == "~/src/foo"
        assert entry.state == StatusState.WORKING

    def test_local_hostname_is_skipped(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(host=_LOCAL)})
        assert not c._sessions

    def test_empty_host_is_skipped(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(host="")})
        assert not c._sessions

    def test_ignored_cwd_is_skipped(self):
        c = _make_controller()
        c._settings.ignore_regex = "~/src/.*"
        _poll(c, {"abc": _remote_state()})
        assert not c._sessions

    def test_headless_marked_session_is_skipped(self):
        # claude-wrapper.sh sets headless=true for -p runs; recording rules
        # carry the label into the state metrics — no row.
        c = _make_controller()
        _poll(c, {"abc": _remote_state(headless=True)})
        assert not c._sessions

    def test_unmarked_session_passes(self):
        # No headless label (direct run, old wrapper) — interactive by
        # construction, row created.
        c = _make_controller()
        _poll(c, {"abc": _remote_state()})
        assert _entry_for(c, "abc").remote_host == "remote-host-1"

    def test_existing_entry_updates_not_duplicates(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.WORKING)})
        _poll(c, {"abc": _remote_state(state=StatusState.PERMISSION_REQUIRED)})
        assert len(c._sessions) == 1
        assert _entry_for(c, "abc").state == StatusState.PERMISSION_REQUIRED


class TestRemoteLifecycle:
    def test_ready_renders_as_idle(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.READY)})
        assert _entry_for(c, "abc").state == StatusState.IDLE

    def test_ready_removed_when_metric_absent(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.READY)})
        _poll(c, {})
        _poll(c, {}, at=_AFTER_GRACE)
        assert not c._sessions

    def test_working_removed_when_metric_absent(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.WORKING)})
        _poll(c, {})
        _poll(c, {}, at=_AFTER_GRACE)
        assert not c._sessions
        assert "abc" not in c._session_id_to_pid

    def test_kept_during_grace_when_metric_absent(self):
        # The idle→working metric hole: ready has gone false, working has not
        # counted an event yet. Row must survive it.
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.READY)})
        _poll(c, {}, at=1090.0)
        assert "abc" in c._session_id_to_pid

    def test_grace_resets_when_metric_returns(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.READY)})
        _poll(c, {}, at=1090.0)
        _poll(c, {"abc": _remote_state(state=StatusState.WORKING)}, at=1100.0)
        assert _entry_for(c, "abc").otel_missing_since == 0.0
        # Absence restarts from the return, not from the first miss.
        _poll(c, {}, at=1150.0)
        assert "abc" in c._session_id_to_pid

    def test_permission_sticky_when_metric_absent(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.PERMISSION_REQUIRED)})
        _poll(c, {})
        entry = _entry_for(c, "abc")
        assert entry.state == StatusState.PERMISSION_REQUIRED

    def test_flagged_kept_when_metric_absent(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.READY)})
        _entry_for(c, "abc").flagged = True
        _poll(c, {})
        assert "abc" in c._session_id_to_pid

    def test_dismissed_permission_removed_next_poll(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.PERMISSION_REQUIRED)})
        entry = _entry_for(c, "abc")
        # User dismiss: double-click clears state to IDLE
        entry.state_cleared_from = entry.state.value
        entry.state = StatusState.IDLE
        _poll(c, {})
        assert not c._sessions

    def test_local_stale_working_flip_not_applied_to_remote(self):
        c = _make_controller()
        _poll(c, {"abc": _remote_state(state=StatusState.WORKING)})
        _entry_for(c, "abc").flagged = True  # keep it alive through absence
        _poll(c, {})
        assert _entry_for(c, "abc").state == StatusState.WORKING


class TestRemotePersistence:
    def test_state_key_host_qualified(self):
        entry = _SessionEntry(SessionInfo(pid=-1, session_id="abc", cwd="~/x", started_at=0))
        assert AppController._state_key(entry) == "~/x"
        entry.remote_host = "remote-host-1"
        assert AppController._state_key(entry) == "remote-host-1:~/x"

    def test_saved_state_lookup_does_not_cross_hosts(self):
        c = _make_controller()
        c._saved_state = {"~/src/foo": {"flagged": True}}
        _poll(c, {"abc": _remote_state()})
        assert _entry_for(c, "abc").flagged is False

    def test_restore_sticky_remote_on_startup(self):
        c = _make_controller()
        saved = {
            "state": "permission_required",
            "flagged": False,
            "hidden": False,
            "last_active": 123.0,
            "state_cleared_from": "",
            "remote_host": "remote-host-1",
            "cwd": "~/src/foo",
            "session_id": "abc",
        }
        c._saved_state = {"remote-host-1:~/src/foo": saved}
        c._restore_remote_from_state(saved)
        entry = _entry_for(c, "abc")
        assert entry.remote_host == "remote-host-1"
        assert entry.state == StatusState.PERMISSION_REQUIRED

    def test_no_restore_for_non_sticky_unflagged(self):
        c = _make_controller()
        saved = {
            "state": "ready",
            "flagged": False,
            "remote_host": "remote-host-1",
            "cwd": "~/src/foo",
            "session_id": "abc",
        }
        c._restore_remote_from_state(saved)
        assert not c._sessions


class TestRemoteSorting:
    def test_remote_block_first_grouped_by_host(self):
        c = _make_controller()
        local = _SessionEntry(SessionInfo(pid=1, session_id="l", cwd="/tmp/aaa", started_at=0))
        # Host wins over path: rows group per machine.
        r1 = _SessionEntry(SessionInfo(pid=-1, session_id="r1", cwd="~/zzz", started_at=0))
        r1.remote_host = "ant"
        r2 = _SessionEntry(SessionInfo(pid=-2, session_id="r2", cwd="~/aaa", started_at=0))
        r2.remote_host = "zebra"
        c._sessions = {1: local, -1: r1, -2: r2}
        ordered = c._sorted_entries()
        assert [e.session.session_id for e in ordered] == ["r1", "r2", "l"]

    def test_same_host_sorted_by_display_text(self):
        c = _make_controller()
        r1 = _SessionEntry(SessionInfo(pid=-1, session_id="r1", cwd="~/zzz", started_at=0))
        r1.remote_host = "same-host"
        r2 = _SessionEntry(SessionInfo(pid=-2, session_id="r2", cwd="~/aaa", started_at=0))
        r2.remote_host = "same-host"
        c._sessions = {-1: r1, -2: r2}
        ordered = c._sorted_entries()
        assert [e.session.session_id for e in ordered] == ["r2", "r1"]


class TestSandboxMatching:
    @staticmethod
    def _sandbox_entry(*, cwd: str, pid: int = -9) -> _SessionEntry:
        entry = _SessionEntry(
            SessionInfo(pid=pid, session_id="sandbox-sb-abc123", cwd=cwd, started_at=0)
        )
        entry.sandbox = True
        return entry

    def _controller_with_sandbox(self) -> AppController:
        c = _make_controller()
        entry = self._sandbox_entry(cwd="/home/u/sandboxes/proj-main")
        c._sessions = {entry.session.pid: entry}
        c._session_id_to_pid = {entry.session.session_id: entry.session.pid}
        return c

    def test_match_by_openshell_name(self):
        c = self._controller_with_sandbox()
        state = SessionState(
            state=StatusState.WORKING,
            host_name="a-machine",
            project="/sandbox/source",
            sandbox_openshell_name="sb-abc123",
        )
        assert c._match_sandbox(state) == -9

    def test_match_by_sandbox_source(self):
        # Sandbox refreshed for sandbox_source but not openshell name yet.
        c = self._controller_with_sandbox()
        state = SessionState(
            state=StatusState.WORKING,
            host_name="a-machine",
            project="/sandbox/source",
            sandbox_source="proj-main",
        )
        assert c._match_sandbox(state) == -9

    def test_match_by_legacy_sandbox_hostname(self):
        # Pre-refresh sandboxes still emit host_name=sandbox-<openshell name>.
        c = self._controller_with_sandbox()
        state = SessionState(
            state=StatusState.WORKING, host_name="sandbox-sb-abc123", project="/sandbox/source"
        )
        assert c._match_sandbox(state) == -9

    def test_no_match_for_plain_host_session(self):
        c = self._controller_with_sandbox()
        state = SessionState(
            state=StatusState.WORKING, host_name="a-machine", project="/home/u/src/x"
        )
        assert c._match_sandbox(state) is None
